import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';

const source = await readFile('dist/main.js', 'utf8');
const module = { exports: {} };
const messages = [];
const game = { time: 1, rooms: {}, creeps: {}, cpu: { tickLimit: 20, bucket: 10000, getUsed: () => 0 } };
const context = vm.createContext({ module, exports: module.exports, Game: game, Memory: {}, console: { log: message => messages.push(message) } });
vm.runInContext(source, context, { filename: 'main.js', timeout: 1000 });
assert.equal(typeof module.exports.loop, 'function');
assert.deepEqual(Object.keys(module.exports.industry.boosts).sort(), ['acknowledge','aliases','cancel','get','list','request']);
assert.equal(vm.runInContext('module.exports.industry.boosts.list().length', context), 0);
assert.deepEqual(Object.keys(module.exports.industry.labs).sort(), ['assignAllBoostRoles','assignBoostRoles','assignBoostRolesForRooms','clearEmpire','clearOverride','clearTemporary','configure','configureEmpire','configureMany','inspect','inspectEmpire','previewAllBoostRoles','previewBoostRoles','previewBoostRolesForRooms','previewEmpire','replanStatus','requestReplan','requestReplans','temporary']);
assert.equal(vm.runInContext("module.exports.industry.labs.inspect('W0N1').owned", context), false);
assert.equal(vm.runInContext('module.exports.industry.labs.inspectEmpire().ok', context), true);
vm.runInContext('module.exports.loop(); module.exports.loop();', context, { timeout: 1000 });
assert.deepEqual(messages, []);
const map = JSON.parse(await readFile('dist/main.js.map', 'utf8'));
assert.ok(map.sources.some(path => path.endsWith('src/main.ts')));
assert.ok(map.sourcesContent.every(content => typeof content === 'string'));
console.log('CommonJS loop loads and runs without Node globals; source map includes original sources.');
